#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8

# Run from the repo root, whatever directory this was started from.
cd "$(dirname "$0")/.."

# Hosted values live here: ignored by git (*.local), and never loaded by Vite,
# so local development and the tests can't point at the real database.
ENV_FILE=".env.hosted.local"

REPO=$(gh repo view --json nameWithOwner -q .nameWithOwner 2>/dev/null \
  || git remote get-url origin | sed -E 's#.*github.com[:/]##; s#\.git$##')
OWNER=${REPO%%/*}
NAME=${REPO##*/}
OWNER_LOWER=$(printf '%s' "$OWNER" | tr '[:upper:]' '[:lower:]')
SITE_URL="https://${OWNER_LOWER}.github.io/${NAME}/"

banner "Present Planner: go live"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Create the Supabase project"
say "By the end, the database is online at Supabase and the app is at"
say "  $SITE_URL"
say "Supabase hosts the shared database. The free plan is enough for a family."
open_url "https://supabase.com/dashboard/new"
step "Sign in (or sign up), and pick or create an organisation if asked."
step "Project name: present-planner"
step "Database password: click Generate, and save it in your password manager."
step "  You'll need it in stage 3. This wizard won't store it."
step "Region: the one nearest you (e.g. West EU (London))."
step "Click Create new project, and wait until the dashboard says it's ready."
step "Copy the project reference: the code after /project/ in the address bar."
note "  e.g. supabase.com/dashboard/project/abcdefghijklmnopqrst"
while true; do
  ask SUPABASE_PROJECT_REF "Paste the project reference:"
  [[ "$SUPABASE_PROJECT_REF" =~ ^[a-z]{20}$ ]] && break
  warn "That doesn't look like a project reference (20 lowercase letters). Try again."
done
write_env SUPABASE_PROJECT_REF "$SUPABASE_PROJECT_REF"
write_env SUPABASE_URL "https://${SUPABASE_PROJECT_REF}.supabase.co"
DASH="https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Log the Supabase CLI in"
say "The command-line tool needs your permission to change the project."
say "This runs 'npx supabase login', which opens a browser to approve it."
pause "Press Enter to run it."
npx supabase login
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Create the tables and access rules"
say "Links this folder to the project, then applies supabase/migrations/:"
for file in supabase/migrations/*.sql; do note "  $(basename "$file")"; done
npx supabase link --project-ref "$SUPABASE_PROJECT_REF"
ask_secret SUPABASE_DB_PASSWORD "Paste the database password from stage 1:"
say "Checking what would be applied (nothing changes yet):"
npx supabase db push --dry-run --password "$SUPABASE_DB_PASSWORD"
if confirm "Apply these migrations to the hosted database now?"; then
  npx supabase db push --password "$SUPABASE_DB_PASSWORD"
else
  SKIPPED+=("Apply migrations: npx supabase db push")
fi
unset SUPABASE_DB_PASSWORD
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Auth settings"
say "Tell Supabase where the app lives, and make sign-in codes 6 digits."
open_url "${DASH}/auth/url-configuration"
step "Site URL: $SITE_URL"
step "Click Save."
note "  If the link lands elsewhere: left menu → Authentication → URL Configuration."
pause "Press Enter when saved."
open_url "${DASH}/auth/providers"
step "Open the Email provider. Keep it enabled."
step "Set Email OTP Length to 6 (the app's code box takes 6 digits). Save."
note "  If it isn't there, look under Authentication → Sign In / Providers."
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Sign-in email"
say "Make sign-in emails carry a 6-digit code instead of a link."
open_url "${DASH}/auth/templates"
say "Edit BOTH the 'Magic Link' and the 'Confirm signup' templates:"
step "Subject: Your Present Planner code"
step "Body (Source): replace everything with the contents of"
step "  supabase/templates/sign-in-code.html, shown here:"
printf '\n'
sed 's/^/      /' supabase/templates/sign-in-code.html
printf '\n'
step "Save each template."
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Connect the app to the database"
say "The app needs the project's publishable key. It's public by design:"
say "the access rules you applied in stage 3 are what protect the data."
open_url "${DASH}/settings/api-keys"
step "Copy the Publishable key (it starts sb_publishable_)."
while true; do
  ask SUPABASE_PUBLISHABLE_KEY "Paste the publishable key:"
  [[ "$SUPABASE_PUBLISHABLE_KEY" == sb_publishable_* ]] && break
  warn "Publishable keys start with sb_publishable_. Don't paste the secret key."
done
write_env SUPABASE_PUBLISHABLE_KEY "$SUPABASE_PUBLISHABLE_KEY"
# The deploy workflow reads these as vars.SUPABASE_URL and
# vars.SUPABASE_PUBLISHABLE_KEY. Variables, not secrets: both are public.
set_var SUPABASE_URL "$SUPABASE_URL"
set_var SUPABASE_PUBLISHABLE_KEY "$SUPABASE_PUBLISHABLE_KEY"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Turn on GitHub Pages"
say "Pages will publish whatever the Deploy workflow builds."
if gh api "repos/$REPO/pages" >/dev/null 2>&1; then
  gh api -X PUT "repos/$REPO/pages" -f build_type=workflow >/dev/null \
    && say "✓ Pages already on; source set to GitHub Actions."
elif gh api -X POST "repos/$REPO/pages" -f build_type=workflow >/dev/null 2>&1; then
  say "✓ Pages turned on, with GitHub Actions as the source."
else
  warn "Couldn't do it from here, so set it by hand:"
  open_url "https://github.com/$REPO/settings/pages"
  step "Build and deployment → Source: GitHub Actions."
  pause "Press Enter when done."
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Deploy and install"
if gh api "repos/$REPO/contents/.github/workflows/deploy.yml?ref=main" >/dev/null 2>&1; then
  if confirm "Publish the app from main now?"; then
    gh workflow run deploy.yml --ref main
    say "Started. Watch it here (about two minutes):"
    open_url "https://github.com/$REPO/actions/workflows/deploy.yml"
  fi
else
  say "The deploy workflow isn't on main yet. Merge the pull requests, and"
  say "every push to main publishes the app from then on."
  SKIPPED+=("Merge to main, then the Deploy workflow publishes $SITE_URL")
fi
say "Then, on your phone, open: $SITE_URL"
step "iPhone: Share → Add to Home Screen."
step "Android: menu (⋮) → Install app (or Add to Home screen)."
pause

finish
}

run_wizard "$@"; exit
